//Ensure that Manager Pane is visible
swModelDocExtension.HideFeatureManager(false);
//Get the tabs in the Manager Pane
tabs = (object[])swModelViewManager.GetFeatureManagerTabs();

// Suppress view
swDraw.SuppressView();
// Display an X where the view was suppressed
swDraw.HideShowDrawingViews();
// Unsuppress view
swDraw.UnsuppressView();

swPageSetup = (PageSetup)swModelDocExt.AppPageSetup;
if (swPageSetup.HighQuality)
{
Debug.Print("Drawing set to print in high quality. Are draft edges scaled? " + swPageSetup.ScaleDraftEdges);
}
